class stringx
{
public:
  char *data;
};

stringx operator+(const stringx& lhs, const char *rhs);
stringx operator+(const char *lhs, const stringx& rhs);

struct str_list_iterator
{
  stringx *current;
};

struct str_list
{
  stringx *start;
  stringx *finish;
  stringx *end_of_storage;
  str_list_iterator begin()
  {
    str_list_iterator result = { start };
    return result;
  }
};

typedef str_list *vm_str_list_t;
typedef str_list_iterator vm_str_list_iterator_t;

class script_instance
{
public:
  const stringx& get_name() const;
};

class script_executable
{
public:
  const stringx& get_fullname() const;
};

class vm_thread
{
public:
  script_instance *get_instance() const;
  script_executable *get_executable() const;
};

class vm_stack
{
public:
  int salloc;
  char *buffer;
  char *SP;
private:
  vm_thread *my_thread;
public:
  char *get_SP() const { return SP; }
  vm_thread *get_thread() const { return my_thread; }
  void move_SP(int n) { SP += n; }
  void pop(int n) { move_SP(-n); }
  bool push(const char *src, int n);
};

void error(const stringx& message);

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
  protected:
    char *name;
  public:
    function(script_library_class *slc, const char *n);
    virtual ~function();
    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()
#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result))) \
    error(stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname())
#define SLF_DONE return true

class slf_str_list_begin_t : public script_library_class::function
  {
  public:
    slf_str_list_begin_t(script_library_class* slc,const char* n) : script_library_class::function(slc,n) {}
    struct parms_t
      {
      vm_str_list_t me;
      };
    virtual bool operator()(vm_stack& stack,entry_t entry)
      {
      SLF_PARMS;
      vm_str_list_iterator_t result = parms->me->begin();
      SLF_RETURN;
      SLF_DONE;
      }
  };
